const { initDB, runFindOrCreate, User, AuditLog } = require('./index');

async function test() {
  await initDB();
  console.log('Database synced');

  // Test 1: Normal user creation
  const result1 = await runFindOrCreate('normal_user');
  console.log('Result for normal_user:', result1 instanceof Error ? result1.message : result1.toJSON());

  const auditLogs1 = await AuditLog.findAll({ where: { username: 'normal_user' } });
  console.log('AuditLog entries for normal_user:', auditLogs1.map(a => a.toJSON()));

  const user1 = await User.findOne({ where: { username: 'normal_user' } });
  console.log('User normal_user exists:', user1 !== null);

  // Test 2: Error user - should roll back both User and AuditLog
  const result2 = await runFindOrCreate('error_user');
  console.log('Result for error_user:', result2 instanceof Error ? result2.message : result2);

  const auditLogs2 = await AuditLog.findAll({ where: { username: 'error_user' } });
  console.log('AuditLog entries for error_user (should be 0):', auditLogs2.length);

  const user2 = await User.findOne({ where: { username: 'error_user' } });
  console.log('User error_user exists (should be false):', user2 !== null);

  process.exit(0);
}

test().catch(err => { console.error(err); process.exit(1); });
"

