  status: { type: DataTypes.STRING },
});

const AuditLog = sequelize.define('AuditLog', {
  action: { type: DataTypes.STRING },
  username: { type: DataTypes.STRING },
});

User.addHook('beforeCreate', async (user, options) => {
  console.log('beforeCreate - options.transaction:', !!options.transaction);
  const auditLogOptions = {};
  if (options.transaction) {
    auditLogOptions.transaction = options.transaction;
  }
  await AuditLog.create({ action: 'Creating user', username: user.username }, auditLogOptions);
});

User.addHook('afterCreate', async (user) => {
  console.log('afterCreate - username:', user.username);
  if (user.username === 'error_user') {
    throw new Error('Simulated failure');
  }
});

async function test() {
  await sequelize.sync({ force: true });

  try {
    const result = await User.findOrCreate({
      where: { username: 'error_user' },
      defaults: { status: 'active' },
    });
    console.log('Result:', result);
  } catch (err) {
    console.log('Caught error:', err.message);
  }

  const users = await User.findAll();
  console.log('Users:', JSON.stringify(users));

  const logs = await AuditLog.findAll();
  console.log('AuditLogs:', JSON.stringify(logs));

  process.exit(0);
}

test().catch(err => { console.error(err); process.exit(1); });
